const BEH=[
{who:"Parents",
 mn:{t:"Look in several times a day and expect push: real-time attendance and entry and exit history, a daily activity diary, messages, tuition reminders and a monthly development and health report (DreamKids). Pick-up registration, growth charts, medicine requests and meal menus are standard parts of MN parent apps.",s:["dreamkids","kids","mega"]},
 k12:{t:"Look in at moments that matter (new grade, exam result, fee, timetable change) rather than daily. US research finds family involvement falls sharply at the move to high school, and parents mostly use portals to check grades; one-way portals and lack of time are the barriers. Vietnamese K12 apps lead with scores, conduct, exams and alerts.",s:["adi_maciver","starkie","sisap_p","vnedu_conn2"]},
 pl:{t:"MN: mobile only, push first. K12: mobile for alerts and quick views; web or PDF and Excel export for results and long forms (SMAS offers web, app and export).",s:["smas_web","fpt_smas"]}},
{who:"Teachers",
 mn:{t:"One or two homeroom teachers with the same children all day: short, frequent logs (attendance, temperature, meals, sleep, hygiene) and approving parent requests, on phones or tablets. On top sits heavy paperwork: plans by year, month, week and day, development records, attendance books and diaries, often duplicated on paper and in software.",s:["sanan_t","tomia_t","gd_net"]},
 k12:{t:"Subject teachers across many classes. Scores are entered per student and per score column on the web, or bulk-imported from an Excel template; phones cover quick score entry, period roll-call and the teaching schedule. Signing học bạ works with a USB token on a PC or on the phone. Circular 29/2024 adds reports to the principal.",s:["smas_excel","sisap_t","vnedu_sign","misa_sign","tt29_a"]},
 pl:{t:"MN: mobile for the daily loop, web for plans and records. K12: both; bulk entry, printing and USB-token signing lean web, single actions lean mobile."}},
{who:"School admins",
 mn:{t:"Run meals and nutrition, health checks twice a year and growth tracking (monthly under 24 months, quarterly after, per the former joint circular), daily care oversight, fee collection and enrolment.",s:["vnedu_doc","gd_growth"]},
 k12:{t:"Run timetabling, two grading regimes (primary comments and levels, secondary scores), exams, statutory records with digital signatures, extra-class registers, health-insurance collection and compliance reporting; the 30 Oct 2026 data clean-up and HCMC's shared data chain raise the stakes.",s:["tt27","tt22","tt29_a","bhyt","moet_6020b"]},
 pl:{t:"Web portal first for both. Mobile only for glance-and-approve; MISA already ships a mobile leader app.",s:["misa_lead"]}},
{who:"Students",
 mn:{t:"Not users. Children are too young; parents and teachers act on their behalf."},
 k12:{t:"Own phones: a survey cited in a Nghệ An study found 100% of high-school students surveyed owned one, averaging 5.4 hours a day. Lớp 10 students pick subject combinations and manage their own homework.",s:["hue_phone","combo_a"]},
 pl:{t:"Mobile-first (a responsive web app is the minimum); long forms and tests also need a desktop view."}}
];

